<script setup>
import {ref,reactive,onMounted,onUnmounted,watch} from 'vue';import {native,api,on,state} from './native.js';import Icon from './Icon.vue';import AppSelect from './AppSelect.vue';import AppOverlay from './AppOverlay.vue';
const engine=ref({phase:'idle',installed:false,riskAccepted:false}),servers=ref([]),error=ref(''),busy=ref(''),showRisk=ref(false),advanced=ref(false),componentOpen=ref(false),refreshing=ref(false);
let saved={};try{saved=JSON.parse(localStorage.getItem('hxz-mobile-game')||'{}');}catch{}
const options=reactive({memoryMB:[0,1024,2048,3072,4096,6144].includes(saved.memoryMB)?saved.memoryMB:0,renderer:['auto','nggl4es','virgl','zink'].includes(saved.renderer)?saved.renderer:'auto',autoUpdate:saved.autoUpdate!==false,autoJoin:saved.autoJoin!==false});
watch(options,v=>localStorage.setItem('hxz-mobile-game',JSON.stringify(v)));const unsubscribe=on('gameEngine',v=>engine.value=v);
async function refresh(){if(refreshing.value)return;refreshing.value=true;error.value='';try{const [e,s]=await Promise.all([native('gameEngine'),api('/api/server-presets')]);engine.value=e;servers.value=s.servers||[];}catch(e){error.value=e.message;}finally{refreshing.value=false;}}
async function action(name,values={}){error.value='';if(!engine.value.riskAccepted&&!['accept','state','cancel'].includes(name)){showRisk.value=true;return;}busy.value=values.id||name;try{const r=await native('gameEngine',{action:name,...values});if(name!=='launch')engine.value=r;}catch(e){error.value=e.message;}finally{busy.value='';}}
async function accept(){await action('accept',{accepted:true});showRisk.value=false;}
const size=v=>(Math.max(0,v||0)/1024/1024).toFixed(1)+' MB';
onMounted(refresh);onUnmounted(unsubscribe);
</script>
<template><section class="content-page mobile-minecraft">
 <header class="page-toolbar"><h1>Minecraft</h1><button class="icon-button" aria-label="刷新游戏配置" :disabled="refreshing" @click="refresh"><Icon name="refresh"/></button></header>
 <div v-if="error" class="game-error" role="alert"><p>{{error}}</p><button class="soft-button" :disabled="refreshing" @click="refresh"><Icon name="refresh"/>重新检查</button></div>
 <p v-if="!state.hasAccount" class="game-login-note"><Icon name="user"/><span>在「我的」登录幻想镇皮肤站后，即可安装并进入服务器。</span></p>
 <div class="server-section-heading"><h2>选择服务器</h2><span class="muted">{{servers.length?servers.length+' 个默认服务器':'获取服务器配置'}}</span></div>
 <div v-if="!servers.length" class="card game-server-empty"><p>{{refreshing?'正在获取服务器…':'暂未取得服务器配置'}}</p><button v-if="!refreshing" class="soft-button" @click="refresh">重新获取</button></div>
 <div class="game-server-list"><article v-for="(server,index) in servers" :key="server.id" class="card mobile-server-card"><div class="engine-heading"><span class="server-number">{{String(index+1).padStart(2,'0')}}</span><div><h2>{{server.name}}</h2><p>{{server.profileSource==='hxzup'?'随服务器整合包更新':[server.version,server.loader||'原版'].filter(Boolean).join(' · ')}}</p></div></div><p v-if="!server.enabled" class="muted">服务器当前未开放</p><p v-else-if="server.updateRequired" class="muted">启动前需要完成服务器更新</p><div class="server-actions"><button class="primary" :disabled="!state.hasAccount||!server.enabled||!!busy||engine.busy" @click="engine.installed?action('launch',{id:server.id,options:{...options}}):action(engine.ready?'install':'download')"><Icon :name="engine.installed?'play':'download'"/>{{busy===server.id?'正在准备…':engine.installed?'安装并进入':engine.ready?'安装运行组件':'准备游戏环境'}}</button><button class="soft-button" :disabled="!engine.installed||!state.hasAccount||!server.enabled||!!busy||engine.busy" @click="action('launch',{id:server.id,options:{...options,prepareOnly:true}})">仅安装</button></div></article></div>
 <section class="card engine-status"><button class="engine-settings-trigger" :aria-expanded="componentOpen" @click="componentOpen=!componentOpen"><div><h2>游戏运行组件</h2><p>{{engine.busy?(engine.message||'正在准备运行组件'):engine.phase==='error'?'需要重新检查':engine.phase==='paused'?'下载已暂停':engine.installed?'已安装 '+(engine.version||''):engine.ready?'已下载，等待安装':engine.message||'首次进入前需要安装'}}</p></div><Icon name="chevron" :class="{'engine-chevron-open':componentOpen}"/></button>
  <div v-if="engine.busy" class="engine-download" aria-live="polite"><progress v-if="engine.total>0" :value="engine.received||0" :max="engine.total"/><progress v-else aria-label="正在准备运行组件"/><p>{{engine.total>0?size(engine.received)+' / '+size(engine.total):engine.received? '已接收 '+size(engine.received):'正在连接，请稍候…'}}</p><button class="soft-button" :disabled="!!busy" @click="action('cancel')">暂停下载</button></div>
  <p v-if="engine.phase==='error'||engine.phase==='paused'" class="runtime-message" :class="{'is-error':engine.phase==='error'}" role="status">{{engine.message}}</p>
  <div v-if="componentOpen" class="engine-component-options"><p class="muted">运行组件负责启动手机游戏；服务器与整合包可在上方选择。</p><div class="component-actions"><button v-if="!engine.installed" class="primary" :disabled="!!busy||engine.busy" @click="action(engine.ready?'install':'download')"><Icon name="download"/>{{engine.ready?'安装组件':'下载运行组件'}}</button><button v-else class="soft-button" :disabled="!!busy||engine.busy" @click="action('settings')"><Icon name="settings"/>触控与高级设置</button><button v-if="engine.installed" class="soft-button" :disabled="!state.hasAccount||!!busy||engine.busy" @click="action('importAccount')">导入社区账号</button><button v-if="engine.installed" class="soft-button" :disabled="!!busy||engine.busy" @click="action(engine.ready?'install':'download')">{{engine.ready?'安装组件更新':'检查组件更新'}}</button><button class="soft-button" @click="showRisk=true">运行提示</button></div></div>
 </section>
 <section class="card mobile-runtime-settings"><button class="engine-settings-trigger" :aria-expanded="advanced" @click="advanced=!advanced"><div><h2>运行设置</h2><p>内存、渲染器与自动更新</p></div><Icon name="chevron" :class="{'engine-chevron-open':advanced}"/></button><div v-if="advanced" class="runtime-options"><label>内存分配<AppSelect v-model="options.memoryMB" label="游戏内存" :options="[{value:0,label:'自动分配'},... [1024,2048,3072,4096,6144].map(v=>({value:v,label:(v/1024)+' GB'}))]"/></label><label>渲染器<AppSelect v-model="options.renderer" label="渲染器" :options="[{value:'auto',label:'自动检测并适配设备'},{value:'nggl4es',label:'NG-GL4ES · 优先兼容'},{value:'virgl',label:'VirGL · 图形兼容'},{value:'zink',label:'Zink · 需要 Vulkan 支持'}]"/></label><label class="engine-switch"><span>启动前更新整合包</span><input v-model="options.autoUpdate" type="checkbox"></label><label class="engine-switch"><span>启动后自动进入服务器</span><input v-model="options.autoJoin" type="checkbox"></label></div></section>
 <AppOverlay :open="showRisk" label="手机游戏运行提示" kind="confirm" @close="showRisk=false"><section class="sheet engine-risk-dialog"><header class="sheet-header"><h2>先了解手机运行条件</h2><button class="icon-button" aria-label="关闭" @click="showRisk=false"><Icon name="close"/></button></header><div class="sheet-body engine-risk-body"><p>这是独立的 ARM64 Java 游戏运行组件，基于 FCL 开源运行环境。社区和语音继续留在幻想镇社区中。</p><ul><li>电脑模组不保证支持手机，大型整合包可能无法启动。</li><li>安装会下载数 GB 内容；建议连接 Wi-Fi，预留存储和内存。</li><li>游戏可能发热、耗电或被系统回收。提高内存不一定更快。</li><li>皮肤站登录令牌仅传给同签名的本地组件，不写入启动请求文件。</li><li>游戏存档在运行组件中；卸载组件前请先备份。</li></ul><button class="primary" :disabled="!!busy" @click="accept">了解并启用</button></div></section></AppOverlay>
</section></template>
<style scoped>
.mobile-minecraft{display:flex;flex-direction:column;gap:16px}.mobile-minecraft>*{flex:none;min-width:0}.mobile-minecraft>.card,.mobile-minecraft p,.mobile-minecraft h2{margin:0}.mobile-minecraft h2{font-size:1rem;line-height:1.6;word-break:normal;overflow-wrap:anywhere}.mobile-minecraft>.page-toolbar{padding-bottom:0;flex-wrap:wrap}.game-login-note{display:flex;align-items:flex-start;gap:10px;color:var(--muted);font-size:.86rem;line-height:1.7}.game-login-note>.icon{flex:none;margin-top:3px}.game-login-note>span{min-width:0}.server-section-heading{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px 12px}.server-section-heading>.muted{font-size:.78rem}.game-server-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:14px}.mobile-server-card{display:grid;gap:14px;align-content:start;margin:0}.engine-heading{display:flex;gap:12px;align-items:flex-start;min-width:0}.engine-heading>div{min-width:0;flex:1}.engine-heading p{margin-top:5px;color:var(--muted);overflow-wrap:anywhere;line-height:1.6;font-size:.86rem}.server-number{font-weight:650;font-variant-numeric:tabular-nums;font-size:1.1rem;color:var(--accent);background:var(--accent-soft);width:36px;height:36px;display:grid;place-items:center;border-radius:10px;flex:none}.server-actions{display:flex;flex-wrap:wrap;gap:10px}.server-actions>button{min-height:46px;min-width:0}.server-actions>.primary{flex:2 1 10.5em}.server-actions>.soft-button{flex:1 1 5.5em}.engine-status,.mobile-runtime-settings{display:grid;gap:14px}.engine-settings-trigger{display:flex;gap:12px;align-items:center;justify-content:space-between;background:none;border:0;padding:0;color:inherit;text-align:left;min-height:44px;width:100%}.engine-settings-trigger>div{min-width:0;flex:1}.engine-settings-trigger p{font-size:.82rem;color:var(--muted);line-height:1.7;margin-top:4px;overflow-wrap:anywhere}.engine-settings-trigger>.icon{flex:none}.engine-chevron-open{transform:rotate(90deg)}.engine-component-options,.runtime-options{display:grid;gap:16px;min-width:0}.component-actions{display:flex;flex-wrap:wrap;gap:10px}.component-actions>button{flex:1 1 160px;min-width:0;min-height:44px}.runtime-options>label{display:grid;gap:8px;min-width:0;font-size:.9rem;line-height:1.6}.runtime-options :deep(.app-select){min-width:0;width:100%}.runtime-options .engine-switch{display:flex;gap:16px;justify-content:space-between;align-items:center}.engine-switch>span{min-width:0}.engine-switch input{width:24px;height:24px;flex:none;min-height:24px}.engine-download{display:grid;gap:12px;min-width:0}.engine-download p{font-size:.85rem;line-height:1.6;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.mobile-minecraft progress{width:100%;max-width:100%;height:8px;accent-color:var(--accent)}.game-error,.runtime-message{padding:14px;border:1px solid var(--danger);background:var(--danger-bg);border-radius:12px;line-height:1.7;color:var(--danger);overflow-wrap:anywhere}.runtime-message{border-color:var(--line);background:var(--soft);color:var(--muted)}.runtime-message.is-error{border-color:var(--danger);background:var(--danger-bg);color:var(--danger)}.game-error{display:grid;gap:12px}.game-error>button{justify-self:start;min-height:44px}.game-server-empty{display:grid;gap:12px}.game-server-empty p{line-height:1.7}.engine-risk-dialog{border-radius:24px;overflow:hidden}.engine-risk-body{display:grid;gap:16px}.engine-risk-body p{line-height:1.7}.engine-risk-body ul{margin:0;padding-left:20px;line-height:1.7}.engine-risk-body li+li{margin-top:10px}.engine-risk-body .primary{min-height:46px;white-space:normal}
</style>